void MLP(hls::stream< ap_axis<32,2,5,6> > &in_data,
	     hls::stream< ap_axis<32,2,5,6> > &out_data)
{
#pragma HLS INTERFACE axis port=in_data
#pragma HLS INTERFACE axis port=out_data

    float input_features[INPUT_NODES] = {}; // input layer
    float hidden_layer_1[HIDDEN_NODES_1] = {}; // hidden layer 1
    float hidden_layer_2[HIDDEN_NODES_2] = {}; // hidden layer 2
    float output_layer[OUTPUT_NODES] = {}; // output layer

    int n = 0;
    ap_axis<32,2,5,6> tmp;
    // change to for loop
    while(1){
        in_data.read(tmp);
        input_features[n] = in_data.to_float();
        cout << input_features[n] << endl;
        n += 1;
        if(tmp.last){
            break;
        }
    }

    // Input layer to hidden layer 1
    for(int i = 0; i < HIDDEN_NODES_1; i++){
        for(int j = 0; j < INPUT_NODES; j++){
            hidden_layer_1[i] += input_features[j] * weights_1[i + j * HIDDEN_NODES_1];
        }
        // Add bias 
        hidden_layer_1[i] += hidden_bias_1[i];
        // ReLU
        if (hidden_layer_1[i] < 0) {
            hidden_layer_1[i] = 0;
        }
    }

    // Hidden layer 1 to hidden layer 2
    for(int i = 0; i < HIDDEN_NODES_2; i++){
        for(int j = 0; j < HIDDEN_NODES_1; j++){
            hidden_layer_2[i] += hidden_layer_1[j] * weights_2[i + j * HIDDEN_NODES_2];
        }
        // Add bias
        hidden_layer_2[i] += hidden_bias_2[i];
        // ReLU
        if (hidden_layer_1[i] < 0) {
            hidden_layer_1[i] = 0;
        }
    }

    // Hidden layer 2 to output layer
    for(int i = 0; i < OUTPUT_NODES; i++){
        for(int j = 0; j < HIDDEN_NODES_2; j++){
            hidden_layer_2[i] += hidden_layer_1[j] * weights_2[i + j * OUTPUT_NODES];
        }
        // Add bias
        output_layer[i] += output_bias[i];
        cout << output_layer[i] << endl;
    }

    // Don't need to use softmax here  
    for (int i = 0; i < OUTPUT_NODES; i++) {
    	tmp.data = output_layer[i];
    	if (i == OUTPUT_NODES-1) {
    		tmp.last = 1;
    	} else {
    		tmp.last = 0;
    	}
    	out_data.write(tmp);
    }

}
